def carry_over_linked_entries(apps, schema_editor):
    """
    0008 linked each invite to ONE email-history entry. Turn each such link
    into that invite's code #1 history row so the entry keeps its code
    label. The only plaintext source is the old short-lived staff copy
    (present only while that code was still active): it is re-encrypted
    under the new per-issue binding; otherwise the value is simply not
    available (never guessed, never recovered from the hash).
    """
    from portal import otp_vault

    Invite = apps.get_model("portal", "PortalInvite")
    Issue = apps.get_model("portal", "PortalOtpIssue")
    for invite in Invite.objects.exclude(code_message=None).iterator():
        issued_at = invite.otp_issued_at or invite.created_at
        issue = Issue(
            invite=invite, sequence=1, kind="invitation", issued_at=issued_at,
            expires_at=invite.otp_expires_at or issued_at + timedelta(minutes=30),
            message_id=invite.code_message_id,
            used_at=invite.last_verified_at if not invite.otp_digest else None,
        )
        code = otp_vault.unseal_legacy_invite_copy(invite.otp_staff_copy, invite.token)
        issue.otp_ciphertext = otp_vault.seal(f"{invite.token}:{issue.ref}", code) if code else ""
        issue.save()


